174:  * destination are the same pixmap and overlap, rows and columns are walked in
175:  * the order that reads each pixel before it is overwritten. */
176: static void copy_region(Display *dpy, GC gc, const struct XshimPixmap *src,
177:                         struct XshimPixmap *dst, int sx, int sy,
178:                         unsigned int w, unsigned int h, int dx, int dy) {
